// compose-kit/compose.mjs: checks for YOUR composed program, run from the program's directory.
//   node compose-kit/compose.mjs check   manifest, module files and declarations, as the platform checks them
//   node compose-kit/compose.mjs test    your module contract tests (node --test tests/)
import { readFileSync, existsSync, readdirSync } from 'node:fs';
import path from 'node:path';
import vm from 'node:vm';
import { spawnSync } from 'node:child_process';
import { manifestProblems } from './runtime.mjs';
import { sourceProblems, scriptOf } from './loader.mjs';

const dir = process.cwd();
const cmd = process.argv[2] ?? 'check';

function vocabulary() {
  const ops = [];
  const api = path.join(dir, 'api');
  if (existsSync(api)) for (const f of readdirSync(api).filter(x => x.endsWith('.schema.json'))) {
    const s = JSON.parse(readFileSync(path.join(api, f), 'utf8'));
    const sys = s.system ?? f.replace('.schema.json', '');
    for (const op of Object.keys(s.ops ?? {})) ops.push(`${sys}.${op}`);
  }
  return { ops: ops.length ? ops : null, taskKinds: ['fraudReview'] };
}

function check() {
  const mf = path.join(dir, 'composition.json');
  if (!existsSync(mf)) return ['composition.json is missing'];
  let m;
  try { m = JSON.parse(readFileSync(mf, 'utf8')); } catch (e) { return [`composition.json: ${e.message}`]; }
  const out = manifestProblems(m, vocabulary());
  if (out.length) return out;
  for (const [who, d] of [['parent', m.parent], ...Object.entries(m.modules)]) {
    const p = path.join(dir, d.file);
    if (!existsSync(p)) { out.push(`${who}: ${d.file} is missing`); continue; }
    const src = readFileSync(p, 'utf8');
    const sp = sourceProblems(src);
    if (sp.length) { out.push(...sp.map(x => `${d.file}: ${x}`)); continue; }
    try { new vm.Script(scriptOf(src), { filename: d.file }); } catch (e) { out.push(`${d.file}: syntax: ${e.message}`); continue; }
    const fns = who === 'parent' ? ['tick'] : ['step', 'onEvent'];
    if (!fns.some(f => new RegExp(`export\\s+function\\s+${f}\\b`).test(src))) out.push(`${d.file}: exports none of ${fns.join(', ')}`);
    if (who !== 'parent' && !existsSync(path.join(dir, 'tests', `${who}.test.mjs`))) out.push(`${who}: no contract tests (tests/${who}.test.mjs)`);
  }
  return out;
}

if (cmd === 'check') {
  const p = check();
  if (p.length) { console.log(`${p.length} problem(s):\n${p.map(x => `  - ${x}`).join('\n')}`); process.exit(1); }
  console.log('composition: OK');
} else if (cmd === 'test') {
  const r = spawnSync(process.execPath, ['--test', '--test-concurrency=1', 'tests/*.test.mjs'], { cwd: dir, stdio: 'inherit' });
  process.exit(r.status ?? 1);
} else { console.log('usage: node compose-kit/compose.mjs check | test'); process.exit(2); }
// compose-kit/kit.mjs: run one module of YOUR composed program exactly as the platform's composition runtime does
// (same isolation, schema checks, declaration checks), for contract tests. No platform, world or grading inside.
//   import { moduleHarness } from '../compose-kit/kit.mjs';
//   const pay = moduleHarness('payment');                       // reads ../composition.json and the module file
//   const r = pay.step({ ...input }, { key: 'ORD-1-F1', state: null, now: '2026-03-02T10:00:00+01:00', files, query, status });
//   r.output, r.state, r.effects (keys as you wrote them), r.obligations, r.humanTasks, r.violations, r.error
//   const r2 = pay.onEvent({ type: 'effect.result', payload: { key: 'charge', ... } }, { key: 'ORD-1-F1', state: r.state, now });
import { readFileSync } from 'node:fs';
import path from 'node:path';
import vm from 'node:vm';
import { createComposedSolver, kindsOfE8 } from './runtime.mjs';
import { loadProgram } from './loader.mjs';

const strip = (who, key, name) => (typeof name === 'string' && name.startsWith(`${who}/${key}/`) ? name.slice(who.length + key.length + 2) : name);

/** moduleHarness(id, { dir }) → { step(input, opts), onEvent(event, opts) } for module `id` of the program in `dir`. */
export function moduleHarness(id, { dir = path.resolve(process.cwd()) } = {}) {
  const manifest = JSON.parse(readFileSync(path.join(dir, 'composition.json'), 'utf8'));
  const decl = manifest.modules?.[id];
  if (!decl) throw new Error(`no module ${id} in composition.json`);
  const sources = { [decl.file]: readFileSync(path.join(dir, decl.file), 'utf8'), '__parent.mjs': 'export function tick(input, ctx) { return null; }' };
  // A one-module program: a test parent that makes exactly one call (or one delivery) and reports what came back.
  const testManifest = { version: 1, parent: { file: '__parent.mjs', calls: [id], effects: [] }, modules: { [id]: decl } };
  const prog = loadProgram({ vm, manifest: testManifest, sources });
  if (prog.problems.length) throw new Error(`module ${id} does not load: ${prog.problems.join('; ')}`);
  const run = (kind, arg, { key = 'K', state = null, now = '2026-03-02T10:00:00+01:00', files = {}, query = () => [], status = () => 'not-found' } = {}) => {
    let output, error = null;
    const parent = { tick(input, ctx) {
      try {
        if (kind === 'step') output = ctx.call(id, key, arg);
        else {
          const ev = JSON.parse(JSON.stringify(arg));
          const p = ev.payload ?? {};
          if (ev.type === 'effect.result') { if (typeof p.key === 'string') p.key = `${id}/${key}/${p.key}`; for (const it of p.items ?? []) if (typeof it.key === 'string') it.key = `${id}/${key}/${it.key}`; }
          if (ev.type === 'timer.fired') p.obligationId = `${id}/${key}/${p.obligationId}`;
          if (String(ev.type).startsWith('humanTask.')) p.taskId = `${id}/${key}/${p.taskId}`;
          output = ctx.deliver(ev);
        }
      } catch (e) { error = String(e?.message ?? e); }
      return { decisions: { subject: null }, state: null };
    } };
    const solver = createComposedSolver({ manifest: testManifest, parent, modules: prog.modules, kindsOf: kindsOfE8, mode: 'strict', realm: prog.realm });
    const carry = { cv: 1, p: null, m: state === null ? {} : { [id]: { [key]: state } } };
    const out = solver.tick({ kind: 'case', item: 'test', world: 'test', instance: 'i-test', now, events: [], carry }, { files, query, status: (s, k) => status(s, strip(id, key, k)), instances: () => [] });
    const effects = out.effects.map(e => ({ ...e, ...(e.key ? { key: strip(id, key, e.key) } : {}), ...(e.after ? { after: strip(id, key, e.after) } : {}),
      ...(Array.isArray(e.args?.items) ? { args: { ...e.args, items: e.args.items.map(i => ({ ...i, key: strip(id, key, i.key) })) } } : {}) }));
    return { output: output === undefined ? null : output, state: out.carry.m?.[id]?.[key] ?? null, effects,
      obligations: { upsert: out.obligations.upsert.map(o => ({ ...o, id: strip(id, key, o.id) })), cancel: out.obligations.cancel.map(c => strip(id, key, c)) },
      humanTasks: out.humanTasks.map(t => ({ ...t, id: strip(id, key, t.id) })), violations: out.decisions.composition.violations, error };
  };
  return { step: (input, opts) => run('step', input, opts), onEvent: (event, opts) => run('event', event, opts), declaration: decl };
}
// Loader for builder-written composed programs (research/composition-20261021/HARNESS.md §2.3). $0. Imports nothing:
// bundle.mjs inlines it into the solver.mjs the sandbox runs, and passes `node:vm` in.
//
// Each module file (and the parent) is evaluated in its own vm context: it cannot import anything, cannot see another
// module's code or variables, and reaches the platform only through the ctx object the runtime gives it, built inside
// its own context over a JSON-string bridge (no object of the runtime's realm is handed to module code). This is a
// boundary against a builder's shortcuts (importing a sibling, sharing a global), not a security boundary against
// deliberate escape: the whole program still runs inside the OS sandbox (beds/ebed/host/sandbox-arm.mjs), and the
// harness re-verifies every effect's attribution against the trusted manifest from the journal (trace.mjs).

/** Constructs a module file may not use (best-effort static scan; the vm context enforces the rest). */
export const FORBIDDEN = Object.freeze([
  [/(^|[^.\w$])import\s*[\s{*'"(]/m, 'import (modules cannot import anything; use ctx.call to reach another module)'],
  [/(^|[^.\w$])require\s*\(/, 'require'],
  [/(^|[^.\w$])process\s*\./, 'process'],
  [/(^|[^.\w$])globalThis\b/, 'globalThis'],
  [/(^|[^.\w$])eval\s*\(/, 'eval'],
  [/(^|[^.\w$])Function\s*\(/, 'Function constructor'],
  [/(^|[^\w$])export\s*\{/, 'export { ... } lists (export each function or const directly)'],
  [/(^|[^\w$])export\s*\*/, 'export * from'],
  [/(^|[^\w$])export\s+default\b/, 'export default (export named functions: step, onEvent, tick)'],
  [/(^|[^\w$])export\s+(async\s+)?class\b/, 'export class'],
  [/(^|[^\w$])export\s+(let|var)\b/, 'export let/var (state lives in the runtime, not in module variables)'],
]);

