const strip = (who, key, name) => (typeof name === 'string' && name.startsWith(`${who}/${key}/`) ? name.slice(who.length + key.length + 2) : name);

/** moduleHarness(id, { dir }) → { step(input, opts), onEvent(event, opts) } for module `id` of the program in `dir`. */
