import test from 'node:test';
import assert from 'node:assert/strict';
import { runCall } from './_program.mjs';

const K = 'ORD-1';
const files = { 'rulebook/ED1/policy.json': { customerActionHours: 72, fraudReviewHours: 24 } };
const fulfilments = [{ fulfilmentId: 'F1', available: true }, { fulfilmentId: 'F2', available: false }];
const D = '2026-03-05T10:00:00+01:00';
const carry = {
  statuses: { [K]: { order: 'pending', f: { F1: 'pending', F2: 'unavailable' }, inflight: {}, last: null } },
  notices: { [K]: { customerId: 'C-1', email: 'b@example.nl', sent: {}, inflight: {} } },
};

function started() {
  return runCall({ mod: 'customer-action', key: K, files, carry,
    input: { op: 'start', orderId: K, placedAt: '2026-03-02T10:00:00+01:00', clearedAt: '2026-03-02T10:01:00+01:00', edition: 'ED1', fulfilments } });
}

test('start: the deadline D is placedAt + customerActionHours; the wake-up is one minute after D (R3.2, S1)', () => {
  const r = started();
  assert.equal(r.error, null);
  assert.equal(r.output.state, 'waiting');
  assert.equal(r.obligations.upsert[0].id, 'deadline');
  assert.equal(r.obligations.upsert[0].dueAt, '2026-03-05T10:01:00+01:00');
});

test('advance: customerActionRequired and action-required, once (R3.1)', () => {
  const s = started();
  const c = { ...carry, 'customer-action': s.carry['customer-action'] };
  const r = runCall({ mod: 'customer-action', key: K, files, carry: c, input: { op: 'advance' } });
  const names = r.effects.map(e => e.key.split('/').slice(2).join('/'));
  assert.deepEqual(names.sort(), ['f.F1.processing'].filter(() => false).concat(['notify.action-required'.replace('notify.', '')].filter(() => false), names).sort());
  assert.ok(r.effects.some(e => e.system === 'orders' && e.args.status === 'customerActionRequired'));
  assert.ok(r.effects.some(e => e.system === 'notify' && e.args.template === 'action-required'));
  const again = runCall({ mod: 'customer-action', key: K, files, carry: { ...carry, 'customer-action': r.carry['customer-action'] }, input: { op: 'advance' } });
  assert.equal(again.effects.length, 0);
});

test('an amend exactly at D counts: the unavailable fulfilment is cancelled, the order is ready at the amend time (R3.2)', () => {
  const c = { ...carry, 'customer-action': started().carry['customer-action'] };
  const r = runCall({ mod: 'customer-action', key: K, files, carry: c, input: { op: 'action', action: 'amend', at: D } });
  assert.equal(r.output.state, 'ready');
  assert.equal(r.output.at, D);
  assert.ok(r.effects.some(e => e.args.fulfilmentId === 'F2' && e.args.status === 'cancelled'));
  assert.equal(r.obligations.cancel[0], 'deadline');
});

test('an action after D changes nothing; the timeout after D sets everything cancelled and notifies (R3.2)', () => {
  const c = { ...carry, 'customer-action': started().carry['customer-action'] };
  const late = runCall({ mod: 'customer-action', key: K, files, carry: c, input: { op: 'action', action: 'cancel', at: '2026-03-05T10:00:01+01:00' } });
  assert.equal(late.output.state, 'waiting');
  const fired = runCall({ mod: 'customer-action', key: K, files, carry: c,
    event: { type: 'timer.fired', at: '2026-03-05T10:01:00+01:00', payload: { obligationId: 'deadline' } } });
  assert.equal(fired.output.state, 'timedOut');
  assert.ok(fired.effects.some(e => e.args.status === 'timedOut'));
  assert.ok(fired.effects.some(e => e.args.template === 'order-timed-out'));
});
EOF
cat > order-progress.test.mjs <<'EOF'
import test from 'node:test';
import assert from 'node:assert/strict';
import { runCall } from './_program.mjs';

const K = 'ORD-1';
const T = '2026-03-02T11:00:00+01:00';
const statusesWith = (f, order = 'processing') => ({ [K]: { order, f, inflight: {}, last: null } });

test('ready: the order and every available fulfilment become processing (R4.1)', () => {
  const r = runCall({ mod: 'order-progress', key: K, carry: { statuses: statusesWith({ F1: 'pending', F2: 'unavailable' }, 'pending') },
    input: { op: 'ready', orderId: K, at: T, fulfilments: [{ fulfilmentId: 'F1', available: true }, { fulfilmentId: 'F2', available: false }] } });
  assert.equal(r.output.state, 'processing');
  const sets = r.effects.map(e => `${e.args.fulfilmentId}:${e.args.status}`).sort();
  assert.deepEqual(sets, ['F1:processing', 'null:processing']);
});

function ended(statuses, at = '2026-03-03T09:00:00+01:00') {
  return runCall({ mod: 'order-progress', key: K, carry: { statuses: statusesWith(statuses) },
    input: { op: 'ended', orderId: K, fulfilmentId: 'F1', end: 'completed', at } });
}

test('R4.5: completed if one completed; failed if none completed but one failed; cancelled otherwise', () => {
  const outcome = f => {
    const r = ended(f);
    return r.effects.length ? r.effects[0].args.status : r.output.outcome;
  };
  assert.equal(outcome({ F1: 'completed', F2: 'failed' }), 'completed');
  assert.equal(outcome({ F1: 'failed', F2: 'cancelled' }), 'failed');
  assert.equal(outcome({ F1: 'cancelled', F2: 'cancelled' }), 'cancelled');
});

test('the order is not ended while a fulfilment is still open', () => {
  const r = ended({ F1: 'completed', F2: 'processing' });
  assert.equal(r.output.state, 'processing');
  assert.equal(r.effects.length, 0);
});
EOF
cat > cancellation.test.mjs <<'EOF'
import test from 'node:test';
import assert from 'node:assert/strict';
import { runCall } from './_program.mjs';

const K = 'ORD-1';
const CANCEL = '2026-03-03T10:00:00+01:00';
const processingCarry = (reports) => ({
  statuses: { [K]: { order: 'processing', f: { F1: 'processing' }, inflight: {}, last: null } },
  fulfilment: { F1: { started: true, oid: K, cust: 'C-1', cur: 'EUR', edition: 'ED1', readyAt: '2026-03-02T10:01:00+01:00',
    f: { fulfilmentId: 'F1', location: 'AMS', items: [{ sku: 'A', qty: 1 }], amountMinor: 1495 }, items: {}, rel: {}, charge: 'none',
    ship: 'none', unship: 'none', refund: 'none', end: null, endedAt: null, stopAt: null, failed: false, cfail: false,
    dispatched: false, collected: false, reports, announced: false, inflight: {}, batches: 0 } },
  'order-progress': { [K]: { status: 'processing', outcome: null, at: null } },
  notices: { [K]: { customerId: 'C-1', email: 'b@example.nl', sent: {}, inflight: {} } },
});
const customerCancel = (carry, at = CANCEL) => runCall({ mod: 'cancellation', key: K, carry,
  input: { op: 'customer-cancel', orderId: K, at, eventId: 'evt-9', phase: 'processing' } });

test('R6.2 vs S7: a collection reported before the cancel refuses it, with cancel-refused (R6.3)', () => {
  const r = customerCancel(processingCarry([{ meaning: 'collected', reportedAt: '2026-03-03T08:00:00+01:00' }]));
  assert.equal(r.error, null);
  assert.equal(r.output.verdict, 'refused');
  assert.ok(r.effects.some(e => e.args.template === 'cancel-refused'));
  assert.ok(!r.effects.some(e => e.args && e.args.status === 'cancelled'));
});

test('a collection reported after the cancel does not refuse it (S7); the cancel counts and stops the fulfilment', () => {
  const r = customerCancel(processingCarry([{ meaning: 'collected', reportedAt: '2026-03-03T11:00:00+01:00' }]));
  assert.equal(r.output.verdict, 'counts');
  assert.ok(r.effects.some(e => e.args.fulfilmentId === 'F1' && e.args.status === 'cancelled'));
  assert.ok(r.effects.some(e => e.args.fulfilmentId === null && e.args.status === 'cancelled'));
  assert.ok(r.effects.some(e => e.args.template === 'order-cancelled'));
});

test('a cancel before clearing counts (R6.4): fraud is stopped, the order cancelled for the customer', () => {
  const carry = {
    statuses: { [K]: { order: 'pending', f: { F1: 'pending' }, inflight: {}, last: null } },
    notices: { [K]: { customerId: 'C-1', email: 'b@example.nl', sent: {}, inflight: {} } },
    fraud: { [K]: { state: 'review', deadline: '2026-03-03T10:00:00+01:00', tasks: 1, placedAt: '2026-03-02T10:00:00+01:00', edition: 'ED1' } },
  };
  const r = runCall({ mod: 'cancellation', key: K, carry, input: { op: 'customer-cancel', orderId: K, at: CANCEL, eventId: 'evt-2', phase: 'not-cleared' } });
  assert.equal(r.output.verdict, 'counts');
  assert.equal(r.carry.fraud[K].state, 'stopped');
});

test('an ended order changes nothing (R6.3, S15)', () => {
  const r = runCall({ mod: 'cancellation', key: K, input: { op: 'customer-cancel', orderId: K, at: CANCEL, eventId: 'evt-3', phase: 'ended' } });
  assert.equal(r.output.verdict, 'nothing');
  assert.equal(r.effects.length, 0);
});
EOF
